import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"О GoSMS API","description":"","frontmatter":{},"headers":[],"relativePath":"guide/about.md","filePath":"guide/about.md"}'),i={name:"guide/about.md"};function s(n,t,l,d,h,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="о-gosms-api" tabindex="-1">О GoSMS API <a class="header-anchor" href="#о-gosms-api" aria-label="Permalink to &quot;О GoSMS API&quot;">​</a></h1><p>GoSMS — это сервис для автоматизации отправки SMS через Android-смартфоны, подключённые к вашему аккаунту. Вы устанавливаете наше приложение на телефон, подключаете его к панели — и телефон становится вашим SMS-шлюзом.</p><p><strong>GoSMS не является SMS-агрегатором</strong> и не берёт деньги за каждое сообщение. Вы платите за подписку на сервис, а сами SMS отправляются через SIM-карты ваших устройств по тарифу вашего мобильного оператора.</p><h2 id="что-можно-делать-через-api" tabindex="-1">Что можно делать через API <a class="header-anchor" href="#что-можно-делать-через-api" aria-label="Permalink to &quot;Что можно делать через API&quot;">​</a></h2><p>Внешний API (<code>/api/ext/v1/</code>) позволяет интегрировать GoSMS в ваши приложения и автоматизации:</p><table tabindex="0"><thead><tr><th>Раздел</th><th>Что доступно</th></tr></thead><tbody><tr><td><strong>SMS</strong></td><td>Отправлять, просматривать историю, удалять записи</td></tr><tr><td><strong>Устройства</strong></td><td>Просматривать список, управлять настройками, удалять</td></tr></tbody></table><h2 id="базовыи-url" tabindex="-1">Базовый URL <a class="header-anchor" href="#базовыи-url" aria-label="Permalink to &quot;Базовый URL&quot;">​</a></h2><p>Все запросы отправляются на:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.gosms.ru/api/ext/v1/</span></span></code></pre></div><h2 id="формат-данных" tabindex="-1">Формат данных <a class="header-anchor" href="#формат-данных" aria-label="Permalink to &quot;Формат данных&quot;">​</a></h2><ul><li>Тело запроса и ответа — <strong>JSON</strong></li><li>Кодировка — <strong>UTF-8</strong></li><li>Даты — формат <strong>ISO 8601</strong>: <code>2024-01-15T10:30:00Z</code></li></ul><h2 id="ограничения" tabindex="-1">Ограничения <a class="header-anchor" href="#ограничения" aria-label="Permalink to &quot;Ограничения&quot;">​</a></h2><ul><li>Максимальная длина SMS: <strong>300 символов</strong></li><li>Название устройства (своё): <strong>до 100 символов</strong></li><li>Все запросы требуют <a href="/guide/auth">авторизации по API-ключу</a></li></ul>',13)])])}const S=a(i,[["render",s]]);export{u as __pageData,S as default};
